// Lamport Clock — minimal implementation
class LamportClock {
  constructor(nodeId) {
    this.nodeId = nodeId;
    this.time = 0;
  }

  // Call before any local event
  tick() {
    this.time++;
    return this.time;
  }

  // Call when preparing to send a message
  // Returns the timestamp to embed in the message
  send() {
    this.time++;
    return this.time;
  }

  // Call when a message arrives with timestamp msgTime
  receive(msgTime) {
    this.time = Math.max(this.time, msgTime) + 1;
    return this.time;
  }

  toString() {
    return `${this.nodeId}@L${this.time}`;
  }
}

// --- Simulate three nodes ---
const A = new LamportClock('A');
const B = new LamportClock('B');
const C = new LamportClock('C');

// A does a local event, then sends to B
A.tick();                   // A: L=1 (local event)
const ts1 = A.send();       // A: L=2 (send to B)
console.log('A sends:', ts1); // 2

B.receive(ts1);             // B: L=max(0,2)+1=3
console.log('B receives:', B.time); // 3

const ts2 = B.send();       // B: L=4 (send to C)
C.receive(ts2);             // C: L=max(0,4)+1=5
console.log('C receives:', C.time); // 5

// A does an independent local event — concurrent with B and C activity
A.tick();                   // A: L=3 (independent — no causal link to B/C)
console.log('A concurrent event:', A.time); // 3
// L(A concurrent)=3 < L(C)=5 — but A's event did NOT cause C's event!
// This demonstrates the converse does NOT hold.
console.log('Lamport order does not imply causality here');

// To get a total order, combine timestamp with nodeId as tiebreaker
function totalOrder(ts, nodeId) {
  return { ts, nodeId };
}
function compare(a, b) {
  if (a.ts !== b.ts) return a.ts - b.ts;
  return a.nodeId < b.nodeId ? -1 : 1; // lexicographic tiebreak
}

// Vector Clock — full implementation with concurrency detection
class VectorClock {
  constructor(nodeId, allNodes) {
    this.nodeId = nodeId;
    this.clock = {};
    for (const id of allNodes) {
      this.clock[id] = 0;
    }
  }

  // Local event: increment own component only
  tick() {
    this.clock[this.nodeId]++;
    return { ...this.clock };
  }

  // Before sending: tick, return snapshot to embed in message
  send() {
    this.clock[this.nodeId]++;
    return { ...this.clock };
  }

  // On receive: merge (max per component), then tick own
  receive(remoteVector) {
    for (const [node, time] of Object.entries(remoteVector)) {
      if (this.clock[node] === undefined) this.clock[node] = 0;
      this.clock[node] = Math.max(this.clock[node], time);
    }
    this.clock[this.nodeId]++;
  }

  snapshot() {
    return { ...this.clock };
  }

  // Static comparison: A happened-before B?
  // A < B means: A[i] <= B[i] for all i, AND A != B
  static happensBefore(a, b) {
    const nodes = new Set([...Object.keys(a), ...Object.keys(b)]);
    let hasStrictlyLess = false;
    for (const n of nodes) {
      const ai = a[n] ?? 0;
      const bi = b[n] ?? 0;
      if (ai > bi) return false;      // a[n] > b[n] => a NOT <= b
      if (ai < bi) hasStrictlyLess = true;
    }
    return hasStrictlyLess;           // must differ in at least one spot
  }

  static concurrent(a, b) {
    return !VectorClock.happensBefore(a, b) &&
           !VectorClock.happensBefore(b, a);
  }
}

// --- Simulation ---
const nodes = ['A', 'B', 'C'];
const A = new VectorClock('A', nodes);
const B = new VectorClock('B', nodes);
const C = new VectorClock('C', nodes);

const v_a1 = A.tick();          // A: {A:1, B:0, C:0}
const v_send = A.send();        // A: {A:2, B:0, C:0}
B.receive(v_send);              // B: {A:2, B:1, C:0}
const v_b1 = B.snapshot();      // capture B's state
const v_bsend = B.send();       // B: {A:2, B:2, C:0}
C.receive(v_bsend);             // C: {A:2, B:2, C:1}
const v_c1 = C.snapshot();

// Independent event on A — concurrent with everything on B and C
const v_a2 = A.tick();          // A: {A:3, B:0, C:0}

console.log('a1 -> b1?', VectorClock.happensBefore(v_a1, v_b1)); // true
console.log('b1 -> c1?', VectorClock.happensBefore(v_b1, v_c1)); // true
console.log('a1 -> c1?', VectorClock.happensBefore(v_a1, v_c1)); // true (transitivity)
console.log('a2 concurrent b1?', VectorClock.concurrent(v_a2, v_b1)); // true
console.log('a2 concurrent c1?', VectorClock.concurrent(v_a2, v_c1)); // true
